/* nama laut dan rantau untuk hiasan peta */
const LABEL_PETA = [
  { n: 'SELAT MELAKA', c: [99.6, 3.6], r: -38 },
  { n: 'LAUT CHINA SELATAN', c: [111.5, 11.5], r: 0 },
  { n: 'LAUT JAWA', c: [111, -5.0], r: 0 },
  { n: 'LAUTAN HINDI', c: [92, 0], r: 0 },
  { n: 'TELUK SIAM', c: [101.6, 10.0], r: 0 }
];

/* ===== PETA PERJALANAN BERANIMASI (kanvas 2D) =====
   Laluan pahlawan dilukis di atas peta Nusantara. Bila peta dibuka, laluan dilakar
   dari perhentian pertama; bila pemain menang, potret pahlawan belayar ke perhentian
   seterusnya dan kamera mengikutinya. Butang perhentian ialah elemen DOM di atas kanvas
   (boleh ditekan dan dibaca pembaca skrin). Laut beralun perlahan; dihadkan ~30 fps
   dan berhenti bila tiada apa bergerak, tab tersembunyi atau kurang gerakan. */
const Peta = (() => {
  let cv, ctx, lap, W = 0, H = 0, dpr = 1, H0 = null, pts = [], m = 0;
  let cam = { x: 103, y: 3, s: 40 }, camA = null, camB = null, camT = 1, camDur = 1;
  let lakar = 1, lakarT0 = 0, kapal = null, raf = 0, last = 0, t0 = performance.now();
  const img = new Image(); let imgOk = false; img.onload = () => { imgOk = true; minta() };
  const KUR = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const ease = t => t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

  const proj = (c, k = cam) => [(c[0] - k.x) * k.s + W / 2, -(c[1] - k.y) * k.s + H / 2];

  /* kamera yang memuatkan sekumpulan titik, dengan rentang minimum supaya tidak terlalu zum */
  function muat(cs, pad, minSpan) {
    let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
    for (const c of cs) { x0 = Math.min(x0, c[0]); x1 = Math.max(x1, c[0]); y0 = Math.min(y0, c[1]); y1 = Math.max(y1, c[1]) }
    /* ruang lebih di atas untuk potret pahlawan, di bawah untuk nama tempat */
    const dx = Math.max(x1 - x0, minSpan), dy = Math.max(y1 - y0, minSpan * .7), atas = pad + 46, bawah = pad + 30;
    const s = Math.min(120, (W - pad * 2) / dx, (H - atas - bawah) / dy);
    return { x: (x0 + x1) / 2, y: (y0 + y1) / 2 + (atas - bawah) / 2 / s, s };
  }
  function keKamera(k, dur) {
    if (KUR || !dur) { cam = k; camT = 1; return }
    camA = Object.assign({}, cam); camB = k; camT = 0; camDur = dur;
  }

  /* susun atur skrin: perhentian yang jatuh berdekatan (tempat sama atau berjiran pada zum ini)
     dikumpul menjadi satu gugus dan disebar dalam bulatan kecil di sekeliling pusatnya */
  let gugus = [];
  function susun() {
    const raw = pts.map(p => proj(p.c)), g = [];
    raw.forEach((xy, i) => {
      const G = g.find(G => Math.hypot(G.x - xy[0], G.y - xy[1]) < 30);
      if (G) { G.ahli.push(i); G.x = (G.x * (G.ahli.length - 1) + xy[0]) / G.ahli.length; G.y = (G.y * (G.ahli.length - 1) + xy[1]) / G.ahli.length }
      else g.push({ x: xy[0], y: xy[1], ahli: [i] });
    });
    const P = [];
    for (const G of g) {
      const n = G.ahli.length; G.R = n > 1 ? 18 + n * 2 : 0;
      G.ahli.forEach((i, k) => { const a = -Math.PI / 2 + k * 2 * Math.PI / n; P[i] = n > 1 ? [G.x + Math.cos(a) * G.R, G.y + Math.sin(a) * G.R] : [G.x, G.y] });
      G.nama = [...new Set(G.ahli.map(i => pts[i].g))].map(k => pts.find(p => p.g === k).t);
    }
    gugus = g; return P;
  }
  /* lengkung pelayaran antara dua perhentian */
  function lengkung(a, b) {
    const dx = b[0] - a[0], dy = b[1] - a[1], L = Math.hypot(dx, dy) || 1;
    const k = Math.min(.22, 26 / L);
    return [a[0] + dx / 2 - dy * k, a[1] + dy / 2 + dx * k];
  }
  const qb = (a, c, b, t) => [(1 - t) * (1 - t) * a[0] + 2 * (1 - t) * t * c[0] + t * t * b[0], (1 - t) * (1 - t) * a[1] + 2 * (1 - t) * t * c[1] + t * t * b[1]];

  function lukisDarat(t) {
    const g = ctx.createLinearGradient(0, 0, 0, H);
    g.addColorStop(0, '#14202a'); g.addColorStop(1, '#0c141c');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    /* graticule: setiap 5 darjah */
    ctx.strokeStyle = 'rgba(232,194,90,.07)'; ctx.lineWidth = 1; ctx.beginPath();
    for (let lo = 60; lo <= 130; lo += 5) { const [x] = proj([lo, 0]); ctx.moveTo(x, 0); ctx.lineTo(x, H) }
    for (let la = -15; la <= 40; la += 5) { const [, y] = proj([0, la]); ctx.moveTo(0, y); ctx.lineTo(W, y) }
    ctx.stroke();
    /* alun laut: garis pendek di grid tetap, fasa bergerak */
    if (!KUR) {
      ctx.strokeStyle = 'rgba(160,200,220,.10)'; ctx.lineWidth = 1.2; ctx.beginPath();
      const st = Math.max(1.2, 46 / cam.s);
      const lo0 = cam.x - W / 2 / cam.s, lo1 = cam.x + W / 2 / cam.s, la0 = cam.y - H / 2 / cam.s, la1 = cam.y + H / 2 / cam.s;
      for (let la = Math.floor(la0 / st) * st; la < la1; la += st)
        for (let lo = Math.floor(lo0 / st) * st; lo < lo1; lo += st) {
          const j = Math.sin(lo * 12.9898 + la * 78.233) * 43758.5453, f = j - Math.floor(j);
          const [x, y] = proj([lo + f * st * .7, la + ((f * 7) % 1) * st * .7]);
          const ph = Math.sin(t / 900 + f * 6.28) * 3;
          ctx.moveTo(x - 5 + ph, y); ctx.quadraticCurveTo(x + ph, y - 2.5, x + 5 + ph, y);
        }
      ctx.stroke();
    }
    /* darat: halo pantai, isian, garis emas */
    const jalur = () => { ctx.beginPath(); for (const pol of DARAT) { pol.forEach((c, i) => { const [x, y] = proj(c); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y) }); ctx.closePath() } };
    jalur(); ctx.strokeStyle = 'rgba(120,170,190,.16)'; ctx.lineWidth = 7; ctx.lineJoin = 'round'; ctx.stroke();
    ctx.fillStyle = '#3d2a14'; ctx.fill();
    ctx.strokeStyle = '#a97c28'; ctx.lineWidth = 1.3; ctx.stroke();
    /* nama laut */
    ctx.fillStyle = 'rgba(200,178,138,.32)'; ctx.font = `600 ${Math.max(9, Math.min(13, cam.s / 6))}px Cinzel, Georgia, serif`; ctx.textAlign = 'center';
    for (const L of LABEL_PETA) { const [x, y] = proj(L.c); if (x < -80 || x > W + 80 || y < -20 || y > H + 20) continue; ctx.save(); ctx.translate(x, y); ctx.rotate(L.r * Math.PI / 180); ctx.fillText(L.n, 0, 0); ctx.restore() }
  }

  function lukisLaluan(t) {
    const P = susun();
    const nSeg = P.length - 1, sampai = lakar * nSeg;
    for (let i = 0; i < nSeg; i++) {
      if (i >= sampai) break;
      const a = P[i], b = P[i + 1], c = lengkung(a, b), frac = Math.min(1, sampai - i);
      const selesai = i + 1 < m;
      ctx.beginPath(); ctx.moveTo(a[0], a[1]);
      const N = 24; for (let k = 1; k <= N * frac; k++) { const q = qb(a, c, b, k / N); ctx.lineTo(q[0], q[1]) }
      if (selesai) { ctx.setLineDash([]); ctx.strokeStyle = '#e8c25a'; ctx.lineWidth = 2.4 }
      else if (i === m - 1) { ctx.setLineDash([7, 6]); ctx.lineDashOffset = -t / 60; ctx.strokeStyle = 'rgba(232,194,90,.85)'; ctx.lineWidth = 2 }
      else { ctx.setLineDash([2, 6]); ctx.strokeStyle = 'rgba(232,194,90,.35)'; ctx.lineWidth = 1.6 }
      ctx.stroke(); ctx.setLineDash([]);
    }
    /* potret pahlawan */
    let pos;
    if (kapal) { const a = P[kapal.i], b = P[kapal.i + 1]; pos = qb(a, lengkung(a, b), b, ease(kapal.t)) }
    else pos = P[Math.min(m, P.length - 1)];
    if (pos && lakar >= 1) {
      const R = 17, gl = KUR ? 0 : (Math.sin(t / 420) + 1) / 2;
      ctx.beginPath(); ctx.arc(pos[0], pos[1] - 30, R + 6 + gl * 3, 0, 7); ctx.fillStyle = `rgba(232,194,90,${.12 + gl * .1})`; ctx.fill();
      ctx.beginPath(); ctx.moveTo(pos[0], pos[1] - 12); ctx.lineTo(pos[0] - 6, pos[1] - 18); ctx.lineTo(pos[0] + 6, pos[1] - 18); ctx.fillStyle = '#e8c25a'; ctx.fill();
      ctx.save(); ctx.beginPath(); ctx.arc(pos[0], pos[1] - 30, R, 0, 7); ctx.clip();
      if (imgOk) ctx.drawImage(img, pos[0] - R, pos[1] - 30 - R, R * 2, R * 2); else { ctx.fillStyle = '#56131c'; ctx.fill() }
      ctx.restore(); ctx.beginPath(); ctx.arc(pos[0], pos[1] - 30, R, 0, 7); ctx.strokeStyle = '#e8c25a'; ctx.lineWidth = 2.5; ctx.stroke();
    }
    /* nama tempat bagi setiap gugus; jika gugus lain dekat, ke tepi yang lapang */
    const gl = gugus.filter(G => G.ahli[0] <= sampai + .01);
    for (const G of gl) {
      const jir = gl.filter(q => q !== G && Math.hypot(q.x - G.x, q.y - G.y) < 90);
      let lx = G.x, ly = G.y + G.R + 30, al = 'center';
      if (jir.length) { const kiri = jir.some(q => q.x <= G.x); al = kiri ? 'left' : 'right'; lx = G.x + (kiri ? 1 : -1) * (G.R + 20); ly = G.y + 4 - (G.nama.length - 1) * 7 }
      ctx.textAlign = al; ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(0,0,0,.75)';
      G.nama.slice(0, 3).forEach((T, k) => {
        const yy = ly + k * 14;
        ctx.font = '600 11px Cinzel, Georgia, serif'; ctx.fillStyle = '#f1e3c2';
        const tx = T.n + (T.ag ? ' *' : '');
        ctx.strokeText(tx, lx, yy); ctx.fillText(tx, lx, yy);
      });
    }
    return P;
  }

  /* butang DOM di atas kanvas */
  function letakButang(P) {
    const bs = lap.children;
    for (let i = 0; i < bs.length; i++) {
      const b = bs[i], k = +b.dataset.pi, p = P[k];
      const muncul = lakar * Math.max(1, P.length - 1) >= k - .01;
      b.style.transform = `translate(${p[0]}px,${p[1]}px)`;
      b.style.opacity = muncul ? 1 : 0;
    }
  }

  function frame(now) {
    raf = 0;
    if (!cv || cv.offsetParent === null || document.hidden) return;
    if (now - last < 32) { raf = requestAnimationFrame(frame); return }
    last = now;
    let gerak = false;
    if (camT < 1) { camT = Math.min(1, camT + 32 / camDur); const e = ease(camT); cam = { x: camA.x + (camB.x - camA.x) * e, y: camA.y + (camB.y - camA.y) * e, s: camA.s * Math.pow(camB.s / camA.s, e) }; gerak = true }
    if (lakar < 1) { lakar = Math.min(1, (now - lakarT0) / 1400); gerak = true }
    if (kapal) {
      if (now < kapal.mula) gerak = true;
      else { kapal.t = Math.min(1, (now - kapal.mula) / kapal.dur); gerak = true; if (kapal.t >= 1) { const cb = kapal.cb; kapal = null; cb && cb() } }
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    lukisDarat(now - t0);
    const P = lukisLaluan(now - t0);
    letakButang(P);
    /* laut sentiasa beralun perlahan; tanpa gerakan lain, ~15 fps sudah cukup */
    if (!KUR) { if (!gerak) last += 34; raf = requestAnimationFrame(frame) }
    else if (gerak) raf = requestAnimationFrame(frame);
  }
  function minta() { if (!raf) raf = requestAnimationFrame(frame) }

  function saiz() {
    if (!cv) return;
    const r = cv.getBoundingClientRect(); if (!r.width) return;
    dpr = Math.min(2, devicePixelRatio || 1); W = r.width; H = r.height;
    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
    if (H0) { cam = muat(pts.map(p => p.c), 46, 4); camT = 1 }
    minta();
  }

  return {
    pasang(c, l) {
      cv = c; lap = l; ctx = cv.getContext('2d');
      if (typeof ResizeObserver !== 'undefined') new ResizeObserver(saiz).observe(cv); else addEventListener('resize', saiz);
      document.addEventListener('visibilitychange', minta);
    },
    /* tunjuk(H, urutan, kemajuan, {belayar:true} untuk animasi dari m-1 ke m) */
    tunjuk(Hk, urut, maju, opt = {}) {
      const baru = H0 !== Hk; H0 = Hk; m = maju;
      const kira = {};
      pts = urut.map(S => { const T = TEMPAT[S.g] || TEMPAT.melaka; kira[S.g] = (kira[S.g] || 0) + 1; return { g: S.g, c: T.c, k: kira[S.g] - 1, t: T } });
      for (const p of pts) p.n = kira[p.g];
      img.src = PORTRET[Hk.h]; imgOk = img.complete && img.naturalWidth > 0;
      lap.innerHTML = urut.map((S, i) => {
        const T = TEMPAT[S.g] || TEMPAT.melaka, st = i < maju ? 'selesai' : i === maju ? 'kini' : 'kunci';
        const no = S.prolog ? 'P' : (Hk.pr ? i : i + 1);
        return `<button class="pn ${st}" data-pi="${i}" data-i="${i}"${st === 'kunci' ? ' disabled' : ''} aria-label="${S.prolog ? 'Prolog' : 'Perhentian ' + no}: ${esc(S.t)}, ${esc(T.n)}${st === 'kunci' ? ', terkunci' : ''}"><b>${no}</b></button>`;
      }).join('');
      saiz();
      const semua = muat(pts.map(p => p.c), 46, 4);
      if (opt.belayar && maju > 0 && maju < urut.length) {
        /* zum ke pasangan perhentian, kemudian belayar */
        cam = semua; camT = 1; lakar = 1;
        keKamera(muat([pts[maju - 1].c, pts[maju].c], 60, 3), 900);
        kapal = { i: maju - 1, t: 0, mula: performance.now() + (KUR ? 0 : 700), dur: KUR ? 1 : 1600, cb: () => { keKamera(semua, 1100); opt.selesai && opt.selesai() } };
        m = maju;
      } else {
        kapal = null; cam = semua; camT = 1;
        if (baru && !KUR) { lakar = 0; lakarT0 = performance.now() } else lakar = 1;
      }
      minta();
    },
    _keadaan() { return { lakar, kapal: !!kapal, camT, n: pts.length, W, H } }
  };
})();

/* ===== LAGA: satu perlawanan congkak (tiada DOM) =====
   Pembungkus nipis di atas Rules dan AI daripada engine.js permainan utama,
   supaya peraturan Hikayat sama tepat dengan gelanggang biasa.
   Pemain sentiasa pihak 0 (baris bawah); lawan pihak 1. */
const Laga = {
  baru(n, biji, lvl) {
    const b = Array(2 * n + 2).fill(0);
    for (let p = 0; p < 2; p++) for (const i of Rules.holes(n, p)) b[i] = biji;
    return { n, b, p: 0, lvl, over: false, w: null, gerak: 0 };
  },
  sah(s, h) { return !s.over && Rules.own(s.n, s.p, h) && s.b[h] > 0 },
  /* jalankan satu langkah; pulangkan hasil resolve (peristiwa untuk animasi) */
  langkah(s, h) {
    if (!this.sah(s, h)) return null;
    const r = Rules.resolve(s.b, s.n, s.p, h);
    s.b = r.b; s.gerak++;
    if (Rules.over(s.b, s.n)) { this.tamat(s); return r }
    if (!r.extra) s.p = 1 - s.p;
    return r;
  },
  tamat(s) { s.b = Rules.sweep(s.b, s.n); s.over = true; s.w = Rules.winner(s.b, s.n) },
  ai(s) { return AI.pick(s.b, s.n, s.p, s.lvl) },
  skor(s, p) { return s.b[Rules.store(s.n, p)] }
};

/* ===== HIKAYAT PAHLAWAN: antara muka =====
   Rumah (pilih pahlawan) -> Jalan (peta perhentian) -> Adegan -> Laga -> Kad fakta.
   Kalah tidak menamatkan perjalanan: pemain cuba semula perhentian yang sama.
   Kemajuan disimpan dalam localStorage pelayar ini sahaja (dibalut try/catch). */
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const tidur = ms => new Promise(r => setTimeout(r, ms));
const KURANG = matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ---------- simpanan ---------- */
const Simpan = {
  K: 'hikayat-pahlawan.v1', d: { maju: {}, laju: false },
  muat() { try { const v = JSON.parse(localStorage.getItem(this.K)); if (v && v.maju) this.d = Object.assign(this.d, v) } catch (e) {} },
  simpan() { try { localStorage.setItem(this.K, JSON.stringify(this.d)) } catch (e) {} },
  maju(id) { return this.d.maju[id] | 0 },
  menang(id, i) { if (i + 1 > this.maju(id)) { this.d.maju[id] = i + 1; this.simpan() } }
};

/* senarai perhentian sesuatu hikayat; prolog (jika ada) di hadapan */
const urutan = H => (H.pr ? [Object.assign({ prolog: true }, H.pr)] : []).concat(H.st);
const tahapOf = (H, i) => { const u = urutan(H)[i]; return u.prolog ? PROLOG : TAHAP[H.pr ? i - 1 : i] };
const tamatOf = H => Simpan.maju(H.id) >= urutan(H).length;

function cip(j, kecil) {
  const L = LABEL[j] || LABEL.lagenda;
  return `<b class="cip${kecil ? ' sm' : ''}" style="--lc:${L.c}">${L.l}</b>`;
}
function potret(h, nama, o, besar, w) {
  if (h != null && PORTRET[h]) return `<span class="med${besar ? ' lg' : ''}"><img src="${PORTRET[h]}" alt=""></span>`;
  if (w && WATAK[w]) return `<span class="med av${o === 'rekaan' ? ' rek' : ''}${besar ? ' lg' : ''}">${avatarWatak(w)}</span>`;
  const ini = nama.replace(/\(.*?\)/g, '').split(/[\s,]+/).filter(w => /^[A-ZÀ-Ý]/.test(w)).slice(0, 2).map(w => w[0]).join('') || nama[0];
  return `<span class="med sil${o === 'rekaan' ? ' rek' : ''}${besar ? ' lg' : ''}" aria-hidden="true"><i>${esc(ini)}</i></span>`;
}

/* ---------- skrin ---------- */
const lawanP = (S, besar) => potret(S.h, S.l, S.o, besar, S.w);
const Skrin = {
  ke(id) {
    for (const s of document.querySelectorAll('.skrin')) s.hidden = s.id !== id;
    document.body.dataset.skrin = id; scrollTo(0, 0);
  }
};

const Rumah = {
  lukis() {
    $('#label-senarai').innerHTML = Object.keys(LABEL).map(j => `<div><dt>${cip(j)}</dt><dd>${esc(LABEL[j].d)}</dd></div>`).join('');
    $('#senarai').innerHTML = HIKAYAT.map((H, k) => {
      const u = urutan(H), m = Math.min(Simpan.maju(H.id), u.length), done = m >= u.length;
      return `<button class="hero${done ? ' tamat' : ''}" data-h="${k}">
        <span class="hp"><img src="${PORTRET[H.h]}" alt=""></span>
        <span class="hn"><b>${esc(H.n)}</b><small>${esc(H.z)} · ${esc(H.p)}</small></span>
        <span class="hm">${cip(H.j, 1)}<span class="pip" aria-label="${m} daripada ${u.length} perhentian">${u.map((_, i) => `<i class="${i < m ? 'on' : ''}"></i>`).join('')}</span></span>
        ${done ? '<em class="lencana" title="Penghafal Hikayat">Penghafal Hikayat</em>' : ''}</button>`;
    }).join('');
    $('#bwatak').textContent = `Galeri Watak Sampingan (${Object.keys(WATAK).length})`;
    const t = HIKAYAT.filter(tamatOf).length;
    $('#kira').textContent = t ? `${t} daripada ${HIKAYAT.length} hikayat tamat` : `${HIKAYAT.length} hikayat, ${HIKAYAT.reduce((a, H) => a + urutan(H).length, 0)} perhentian`;
  }
};

const Jalan = {
  H: null,
  buka(k) { this.H = HIKAYAT[k]; Skrin.ke('jalan'); this.lukis() },
  lukis(opt) {
    const H = this.H, u = urutan(H), m = Simpan.maju(H.id);
    $('#jkepala').innerHTML = `${potret(H.h, H.n, 'tokoh', 1)}
      <div><p class="eyebrow">Hikayat</p><h2>${esc(H.n)}</h2>
      <p class="meta">${cip(H.j)} <span>${esc(H.z)}</span> · <span>${esc(H.p)}</span></p></div>`;
    $('#jintro').innerHTML = `<p>${esc(H.i)}</p>${H.i2 ? `<p>${esc(H.i2)}</p>` : ''}`;
    Peta.tunjuk(H, u, m, opt || {});
    $('#perhentian').innerHTML = u.map((S, i) => {
      const st = i < m ? 'selesai' : i === m ? 'kini' : 'kunci', T = tahapOf(H, i);
      const no = S.prolog ? 'P' : (H.pr ? i : i + 1);
      return `<li class="ph ${st}"><span class="nod">${no}</span>
        <button class="phb" data-i="${i}"${st === 'kunci' ? ' disabled' : ''}>
          <span class="pt"><b>${esc(S.t)}</b>${cip(S.j, 1)}</span>
          <span class="pl">${st === 'kunci' ? 'Menang perhentian sebelumnya untuk membuka' : `${lawanP(S)}<span>Lawan: ${esc(S.l)}${S.o === 'rekaan' ? ' <i class="rk">rekaan</i>' : ''}</span>`}</span>
          <span class="ps">${st === 'selesai' ? 'Selesai · baca kad' : st === 'kini' ? 'Main · ' + T.n : T.n}</span>
        </button></li>`;
    }).join('');
    const ep = $('#epilog');
    ep.hidden = m < u.length;
    if (m >= u.length) ep.innerHTML = `<p class="eyebrow">Epilog</p><p>${esc(H.e)}</p><p class="src">Sumber: ${esc(H.es)}</p>
      <p class="lencana-besar">Lencana diperoleh: <b>Penghafal Hikayat ${esc(H.n)}</b></p>`;
  }
};

/* ---------- adegan & kad ---------- */
const Lapis = {
  buka(html) { $('#lapis .kertas').innerHTML = html; $('#lapis').hidden = false; $('#lapis .kertas').focus() },
  tutup() { $('#lapis').hidden = true }
};
function kadRekaan(S) {
  return S.r ? `<div class="rekaan"><b>Penyataan rekaan</b><p>${esc(S.r)}</p></div>` : '';
}
/* adegan berbabak: perenggan dibuka satu demi satu, kemudian lawan dan butang Mula */
const DRAMA = 'Narasi didramatisasi untuk permainan; fakta dan sumbernya dalam kad selepas menang. Perlawanan congkak ialah cara permainan ini menceritakan setiap pertemuan, bukan peristiwa sejarah.';
const Adegan = {
  i: 0, babak: 0,
  buka(i) {
    const H = Jalan.H, m = Simpan.maju(H.id);
    if (i < m) return Kad.fakta(i, false);
    this.i = i; this.babak = 0; this.lukis(true);
  },
  lukis(baru) {
    const H = Jalan.H, i = this.i, S = urutan(H)[i], T = tahapOf(H, i);
    const A = Array.isArray(S.a) ? S.a : [S.a], n = this.babak, akhir = n >= A.length - 1;
    const html = `<p class="eyebrow">${S.prolog ? 'Prolog' : 'Perhentian ' + (H.pr ? i : i + 1)} · ${esc(H.n)}</p>
      <h3>${esc(S.t)}</h3>
      <div class="babak">${A.slice(0, n + 1).map((p, k) => `<p class="narasi${k === n && !baru ? ' masuk' : ''}">${esc(p)}</p>`).join('')}</div>
      <p class="langkah" aria-hidden="true">${A.map((_, k) => `<i class="${k <= n ? 'on' : ''}"></i>`).join('')}</p>
      ${akhir ? `<div class="vs">${potret(H.h, H.n, 'tokoh')}<span class="vsx">lawan</span>${lawanP(S)}
        <div class="vsl"><b>${esc(S.l)}</b><small>${JLAWAN[S.o]}</small></div></div>
      ${kadRekaan(S)}
      <p class="tahap">${esc(T.n)} · ${T.biji} biji setiap lubang</p>
      <div class="btns"><button class="btn utama" data-k="mula" data-i="${i}">Mula Perlawanan</button>
      <button class="btn" data-k="tutup">Kembali</button></div>`
      : `<div class="btns"><button class="btn utama" data-k="babak">Seterusnya ›</button>
      <button class="btn" data-k="langkau">Baca semua</button></div>`}
      <p class="drama">${DRAMA}</p>`;
    if (baru) Lapis.buka(html);
    else { $('#lapis .kertas').innerHTML = html; $('#lapis .kertas [data-k]')?.focus() }
  },
  maju(semua) { const A = urutan(Jalan.H)[this.i].a; this.babak = semua ? A.length - 1 : Math.min(this.babak + 1, A.length - 1); this.lukis(false) }
};
const Kad = {
  fakta(i, baru) {
    const H = Jalan.H, S = urutan(H)[i], L = LABEL[S.j], u = urutan(H), akhir = i + 1 >= u.length;
    Lapis.buka(`<p class="eyebrow">${baru ? 'Menang · kad dibuka' : 'Kad perhentian'}</p>
      <h3>${esc(S.t)}</h3>
      ${S.b ? `<p class="narasi penutup">${esc(S.b)}</p>` : ''}
      <p class="label">${cip(S.j)} <span>${esc(L.d)}</span></p>
      ${S.jn ? `<p class="jn">${esc(S.jn)}</p>` : ''}
      <div class="tahu"><b>Apa yang diketahui</b><p>${esc(S.k)}</p></div>
      ${kadRekaan(S)}
      <p class="src">Sumber: ${esc(S.s)}</p>
      <p class="lw">${lawanP(S)}<span>Lawan: ${esc(S.l)} · ${JLAWAN[S.o]}</span></p>
      <div class="btns">${baru && !akhir ? `<button class="btn utama" data-k="seterus" data-i="${i + 1}">Teruskan Perjalanan</button>` : ''}
      ${baru && akhir ? '<button class="btn utama" data-k="peta">Baca Epilog</button>' : ''}
      <button class="btn" data-k="peta">Peta Perjalanan</button></div>`);
  },
  kalah(i, seri) {
    Lapis.buka(`<p class="eyebrow">${seri ? 'Seri' : 'Tewas'}</p><h3>${seri ? 'Sama kuat' : 'Lawan menang kali ini'}</h3>
      <p class="narasi">Perjalanan tidak tamat. Cuba perhentian ini sekali lagi; kad faktanya terbuka bila anda menang.</p>
      <div class="btns"><button class="btn utama" data-k="mula" data-i="${i}">Cuba Lagi</button>
      <button class="btn" data-k="peta">Peta Perjalanan</button></div>`);
  }
};

/* ---------- gelanggang ---------- */
const Gel = {
  s: null, i: 0, sibuk: false, lihat: null, tangan: 0, aktif: -1,
  mula(i) {
    const H = Jalan.H, S = urutan(H)[i], T = tahapOf(H, i);
    this.i = i; this.s = Laga.baru(7, T.biji, T.lvl); this.lihat = this.s.b.slice(); this.sibuk = false; this.tangan = 0; this.aktif = -1;
    $('#lkepala').innerHTML = `<div class="pihak p1">${potret(H.h, H.n, 'tokoh')}<span><b>${esc(H.n)}</b><small>Anda</small></span></div>
      <div class="ltengah"><b>${esc(S.t)}</b><small>${esc(T.n)}</small></div>
      <div class="pihak p2"><span><b>${esc(S.l)}</b><small>${JLAWAN[S.o]}</small></span>${lawanP(S)}</div>`;
    Lapis.tutup(); Skrin.ke('laga'); this.lukis(); this.giliran();
  },
  /* susun atur: ibu pemain di KIRI (dicapai selepas lubang n-1), ibu lawan di KANAN */
  lukis() {
    const n = this.s.n, b = this.lihat, s = this.s;
    const lub = i => {
      const mine = s.p === 0 && !this.sibuk && !s.over && Rules.own(n, 0, i) && b[i] > 0;
      return `<button class="lb${mine ? ' sah' : ''}${this.aktif === i ? ' aktif' : ''}" data-l="${i}"${mine ? '' : ' tabindex="-1"'} aria-label="Lubang ${Rules.own(n, 0, i) ? 'anda' : 'lawan'}, ${b[i]} biji">${biji(b[i], 14)}<em>${b[i]}</em></button>`;
    };
    const top = [], bot = [];
    for (let k = 0; k < n; k++) { top.push(lub(n + 1 + k)); bot.push(lub(n - 1 - k)) }
    $('#papan').innerHTML = `<div class="ibu kiri${this.aktif === n ? ' aktif' : ''}" aria-label="Rumah anda, ${b[n]} biji">${biji(b[n], 40)}<em>${b[n]}</em><small>Rumah anda</small></div>
      <div class="baris atas">${top.join('')}</div><div class="baris bawah">${bot.join('')}</div>
      <div class="ibu kanan${this.aktif === 2 * n + 1 ? ' aktif' : ''}" aria-label="Rumah lawan, ${b[2 * n + 1]} biji">${biji(b[2 * n + 1], 40)}<em>${b[2 * n + 1]}</em><small>Rumah lawan</small></div>`;
    $('#tangan').textContent = this.tangan ? `Dalam genggaman: ${this.tangan} biji` : '';
  },
  pesan(t, cls) { const e = $('#pesan'); e.textContent = t; e.className = 'pesan ' + (cls || '') },
  giliran() {
    const s = this.s;
    if (s.over) return this.akhir();
    if (s.p === 0) { this.pesan('Giliran anda: pilih satu lubang di baris bawah.'); this.lukis() }
    else { this.pesan('Lawan sedang berfikir…'); this.lukis(); setTimeout(() => this.gerakAI(), KURANG ? 200 : 650) }
  },
  async gerakAI() { if (this.s.over || this.s.p !== 1) return; await this.main(Laga.ai(this.s)) },
  async main(h) {
    if (this.sibuk) return;
    const s = this.s, p = s.p;
    if (!Laga.sah(s, h)) return;
    this.sibuk = true;
    const r = Laga.langkah(s, h);
    await this.animasi(r, p);
    this.lihat = s.b.slice(); this.aktif = -1; this.tangan = 0; this.sibuk = false;
    if (!s.over && r.extra && s.p === p) this.pesan(p === 0 ? 'Biji terakhir masuk rumah: main lagi.' : 'Lawan masuk rumah dan main lagi.', 'baik');
    if (!s.over && r.extra) await tidur(KURANG ? 100 : 500);
    this.giliran();
  },
  async animasi(r, p) {
    const d = KURANG ? 25 : Simpan.d.laju ? 40 : 120, v = this.lihat, n = this.s.n;
    for (const e of r.ev) {
      if (e.t === 'pick' || e.t === 'chain') { v[e.i] = 0; this.tangan = e.c; this.aktif = e.i; if (e.t === 'chain') this.pesan('Sambung: angkat ' + e.c + ' biji.'); this.lukis(); await tidur(d * 2) }
      else if (e.t === 'drop') { v[e.i]++; this.tangan = e.left; this.aktif = e.i; this.lukis(); bunyi(e.i === Rules.store(n, p) ? 1 : 0); await tidur(d) }
      else if (e.t === 'capture') {
        this.pesan((p === 0 ? 'Tikam! Anda mengambil ' : 'Lawan menikam dan mengambil ') + e.gain + ' biji.', p === 0 ? 'baik' : 'buruk');
        document.querySelector(`[data-l="${e.o}"]`)?.classList.add('ditikam'); bunyi(2); await tidur(d * 5);
        v[Rules.store(n, p)] += e.gain; v[e.o] = 0; v[e.i] = 0; this.lukis(); await tidur(d * 3);
      }
      else if (e.t === 'nocap') { this.pesan('Tiada tikam: biji belum melepasi rumah sendiri.'); await tidur(d * 4) }
    }
  },
  akhir() {
    const s = this.s, H = Jalan.H, a = Laga.skor(s, 0), b = Laga.skor(s, 1);
    this.lihat = s.b.slice(); this.lukis();
    this.pesan(`Tamat: anda ${a}, lawan ${b}.`, s.w === 0 ? 'baik' : 'buruk');
    setTimeout(() => {
      if (s.w === 0) { Simpan.menang(H.id, this.i); Kad.fakta(this.i, true) }
      else Kad.kalah(this.i, s.w === -1);
    }, KURANG ? 300 : 900);
  }
};

/* biji saga: titik merah dalam lubang; selebihnya diwakili angka */
function biji(c, max) {
  let o = '';
  for (let k = 0; k < Math.min(c, max); k++) o += '<i></i>';
  return `<span class="bj">${o}</span>`;
}

/* bunyi tik kayu yang sangat ringkas (WebAudio); hanya selepas pemain menekan sesuatu */
let AC = null;
function bunyi(jenis) {
  if (Simpan.d.senyap) return;
  try {
    AC = AC || new (window.AudioContext || window.webkitAudioContext)();
    const t = AC.currentTime, o = AC.createOscillator(), g = AC.createGain();
    o.type = 'triangle'; o.frequency.setValueAtTime([620, 880, 300][jenis], t);
    o.frequency.exponentialRampToValueAtTime([380, 520, 120][jenis], t + .08);
    g.gain.setValueAtTime(jenis === 2 ? .18 : .09, t); g.gain.exponentialRampToValueAtTime(.001, t + (jenis === 2 ? .25 : .09));
    o.connect(g).connect(AC.destination); o.start(t); o.stop(t + .3);
  } catch (e) {}
}

/* ---------- pendawaian ---------- */
function wire() {
  document.addEventListener('click', e => {
    const t = e.target.closest('button'); if (!t) return;
    if (t.dataset.h != null) return Jalan.buka(+t.dataset.h);
    if (t.classList.contains('phb') || t.classList.contains('pn')) return Adegan.buka(+t.dataset.i);
    if (t.dataset.l != null) return Gel.main(+t.dataset.l);
    const k = t.dataset.k;
    if (k === 'tutup') Lapis.tutup();
    else if (k === 'mula') Gel.mula(+t.dataset.i);
    else if (k === 'babak') Adegan.maju(false);
    else if (k === 'langkau') Adegan.maju(true);
    else if (k === 'seterus') {        /* kembali ke peta: potret belayar ke perhentian seterusnya, kemudian adegan dibuka */
      const ni = +t.dataset.i; Lapis.tutup(); Skrin.ke('jalan');
      Jalan.lukis({ belayar: true, selesai: () => { if (document.body.dataset.skrin === 'jalan' && $('#lapis').hidden) Adegan.buka(ni) } });
    }
    else if (k === 'peta') { Lapis.tutup(); Skrin.ke('jalan'); Jalan.lukis() }
    else if (k === 'rumah') { Lapis.tutup(); Rumah.lukis(); Skrin.ke('rumah') }
    else if (k === 'keluar') { Skrin.ke('jalan'); Jalan.lukis() }
    else if (k === 'watak') { Galeri.lukis(); Skrin.ke('galeri') }
    else if (k === 'laju') { Simpan.d.laju = !Simpan.d.laju; Simpan.simpan(); lajuLabel() }
    else if (k === 'bunyi') { Simpan.d.senyap = !Simpan.d.senyap; Simpan.simpan(); lajuLabel() }
  });
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && !$('#lapis').hidden) Lapis.tutup();
    /* nombor 1–7 memilih lubang anda dari kiri ke kanan */
    if (document.body.dataset.skrin === 'laga' && /^[1-7]$/.test(e.key)) Gel.main(Gel.s.n - +e.key);
  });
}
function lajuLabel() {
  $('#blaju').textContent = Simpan.d.laju ? 'Kelajuan: laju' : 'Kelajuan: biasa';
  $('#bbunyi').textContent = Simpan.d.senyap ? 'Bunyi: tutup' : 'Bunyi: buka';
}

/* ---------- galeri watak sampingan ---------- */
const Galeri = {
  lukis() {
    const muncul = {};
    for (const H of HIKAYAT) for (const S of urutan(H)) if (S.w) (muncul[S.w] = muncul[S.w] || new Set()).add(H.n);
    const ikut = { tokoh: [], watak: [], rekaan: [] };
    for (const [id, W] of Object.entries(WATAK)) ikut[W.o].push([id, W]);
    $('#gsenarai').innerHTML = Object.keys(ikut).map(o => `<section class="gk"><h3>${JLAWAN[o]} <small>${ikut[o].length}</small></h3>
      <div class="gg">${ikut[o].map(([id, W]) => `<figure class="gw" id="w-${id}">${potret(null, W.n, W.o, 1, id)}
        <figcaption><b>${esc(W.n)}</b><small>${esc(W.d)}</small><em>${[...(muncul[id] || [])].map(esc).join(' · ')}</em></figcaption></figure>`).join('')}</div></section>`).join('');
  }
};

Simpan.muat(); wire(); Peta.pasang($('#pcv'), $('#plap')); lajuLabel(); Rumah.lukis(); Skrin.ke('rumah');
/* pemegang untuk ujian pelayar (tests/hikayat.py) */
window.Hikayat = { Simpan, Jalan, Gel, Laga, HIKAYAT, Peta, WATAK, Adegan };

